&lt;p data-renderer-start-pos=&quot;4765&quot; data-local-id=&quot;adcfa560c32c&quot;&gt;Experience with quantization-aware training, post-training quantization, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;FP8&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;INT8&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;INT4&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;NVFP4&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;MXFP4&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;AWQ&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;GPTQ&lt;/span&gt;, SmoothQuant, or related techniques.&lt;/p&gt;
